-- TeamCraft initial schema.
--
-- Conventions:
--   * Primary keys are UUIDs generated by the application (uuid v4).
--   * Enumerations are stored as TEXT with CHECK constraints so that new
--     values only need a migration that relaxes the constraint.
--   * Released engineering data is never deleted; users are deactivated,
--     not deleted.

-- ---------------------------------------------------------------------------
-- Organisation & authentication
-- ---------------------------------------------------------------------------

-- Users are either local accounts (password) or OIDC accounts (Authentik),
-- which are provisioned on first login and whose role is derived from their
-- IdP groups at every login.
CREATE TABLE users (
    id              UUID PRIMARY KEY,
    username        TEXT        NOT NULL UNIQUE,
    display_name    TEXT        NOT NULL,
    email           TEXT,
    auth_source     TEXT        NOT NULL DEFAULT 'local' CHECK (auth_source IN ('local', 'oidc')),
    password_hash   TEXT,
    oidc_subject    TEXT        UNIQUE,
    role            TEXT        NOT NULL CHECK (role IN ('viewer', 'engineer', 'admin')),
    active          BOOLEAN     NOT NULL DEFAULT TRUE,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_login_at   TIMESTAMPTZ,
    CHECK (auth_source <> 'local' OR password_hash IS NOT NULL),
    CHECK (auth_source <> 'oidc' OR oidc_subject IS NOT NULL)
);

-- Pending OIDC authorization requests (state → nonce + PKCE verifier).
CREATE TABLE oidc_states (
    state          TEXT        PRIMARY KEY,
    nonce          TEXT        NOT NULL,
    pkce_verifier  TEXT        NOT NULL,
    return_to      TEXT        NOT NULL DEFAULT '/',
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Browser sessions. Only the SHA-256 of the session token is stored.
CREATE TABLE sessions (
    token_hash  TEXT        PRIMARY KEY,
    user_id     UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at  TIMESTAMPTZ NOT NULL
);
CREATE INDEX sessions_user_idx ON sessions (user_id);
CREATE INDEX sessions_expires_idx ON sessions (expires_at);

-- Personal access tokens for the REST API. Only the SHA-256 is stored.
CREATE TABLE api_tokens (
    id            UUID PRIMARY KEY,
    user_id       UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    name          TEXT        NOT NULL,
    token_hash    TEXT        NOT NULL UNIQUE,
    token_prefix  TEXT        NOT NULL,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_used_at  TIMESTAMPTZ,
    expires_at    TIMESTAMPTZ
);
CREATE INDEX api_tokens_user_idx ON api_tokens (user_id);

CREATE TABLE projects (
    id           UUID PRIMARY KEY,
    code         TEXT        NOT NULL UNIQUE,
    name         TEXT        NOT NULL,
    description  TEXT        NOT NULL DEFAULT '',
    active       BOOLEAN     NOT NULL DEFAULT TRUE,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Number generators (item numbers per type, change numbers).
CREATE TABLE counters (
    name   TEXT   PRIMARY KEY,
    value  BIGINT NOT NULL
);

-- ---------------------------------------------------------------------------
-- Product data: items, revisions, files (datasets), BOM
-- ---------------------------------------------------------------------------

CREATE TABLE items (
    id          UUID PRIMARY KEY,
    number      TEXT        NOT NULL UNIQUE,
    item_type   TEXT        NOT NULL CHECK (item_type IN ('part', 'assembly', 'document', 'software')),
    unit        TEXT        NOT NULL DEFAULT 'each',
    project_id  UUID        REFERENCES projects (id) ON DELETE SET NULL,
    created_by  UUID        NOT NULL REFERENCES users (id),
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX items_project_idx ON items (project_id);
CREATE INDEX items_type_idx ON items (item_type);

CREATE TABLE revisions (
    id              UUID PRIMARY KEY,
    item_id         UUID        NOT NULL REFERENCES items (id) ON DELETE CASCADE,
    seq             INTEGER     NOT NULL CHECK (seq > 0),
    code            TEXT        NOT NULL,
    state           TEXT        NOT NULL CHECK (state IN ('in_work', 'in_review', 'released', 'obsolete')),
    name            TEXT        NOT NULL,
    description     TEXT        NOT NULL DEFAULT '',
    material        TEXT        NOT NULL DEFAULT '',
    mass_kg         DOUBLE PRECISION CHECK (mass_kg IS NULL OR mass_kg >= 0),
    unit_cost       DOUBLE PRECISION CHECK (unit_cost IS NULL OR unit_cost >= 0),
    checked_out_by  UUID        REFERENCES users (id),
    checked_out_at  TIMESTAMPTZ,
    created_by      UUID        NOT NULL REFERENCES users (id),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    released_at     TIMESTAMPTZ,
    UNIQUE (item_id, seq),
    UNIQUE (item_id, code)
);
CREATE INDEX revisions_state_idx ON revisions (state);
CREATE INDEX revisions_checked_out_idx ON revisions (checked_out_by) WHERE checked_out_by IS NOT NULL;
-- An item can have at most one revision that is still being worked on.
CREATE UNIQUE INDEX revisions_one_open_per_item ON revisions (item_id) WHERE state IN ('in_work', 'in_review');

-- File attachments ("datasets"). The bytes live in the content-addressed
-- vault on disk, keyed by sha256. Several rows may share one blob.
CREATE TABLE files (
    id            UUID PRIMARY KEY,
    revision_id   UUID        NOT NULL REFERENCES revisions (id) ON DELETE CASCADE,
    filename      TEXT        NOT NULL,
    content_type  TEXT        NOT NULL,
    size_bytes    BIGINT      NOT NULL CHECK (size_bytes >= 0),
    sha256        TEXT        NOT NULL,
    uploaded_by   UUID        NOT NULL REFERENCES users (id),
    uploaded_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX files_revision_idx ON files (revision_id);
CREATE INDEX files_sha256_idx ON files (sha256);

-- Bill of materials: a parent *revision* uses a child *item*; which child
-- revision is shown is decided at read time by a revision rule.
CREATE TABLE bom_lines (
    id                  UUID PRIMARY KEY,
    parent_revision_id  UUID             NOT NULL REFERENCES revisions (id) ON DELETE CASCADE,
    child_item_id       UUID             NOT NULL REFERENCES items (id),
    find_number         INTEGER          NOT NULL CHECK (find_number > 0),
    quantity            DOUBLE PRECISION NOT NULL CHECK (quantity > 0),
    notes               TEXT             NOT NULL DEFAULT '',
    created_at          TIMESTAMPTZ      NOT NULL DEFAULT now(),
    UNIQUE (parent_revision_id, find_number)
);
CREATE INDEX bom_lines_child_idx ON bom_lines (child_item_id);

-- ---------------------------------------------------------------------------
-- Change management (change orders carrying revisions to release)
-- ---------------------------------------------------------------------------

CREATE TABLE changes (
    id            UUID PRIMARY KEY,
    number        TEXT        NOT NULL UNIQUE,
    title         TEXT        NOT NULL,
    description   TEXT        NOT NULL DEFAULT '',
    priority      TEXT        NOT NULL DEFAULT 'normal' CHECK (priority IN ('low', 'normal', 'high', 'critical')),
    status        TEXT        NOT NULL CHECK (status IN ('draft', 'in_review', 'rejected', 'released', 'cancelled')),
    created_by    UUID        NOT NULL REFERENCES users (id),
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    submitted_at  TIMESTAMPTZ,
    closed_at     TIMESTAMPTZ
);
CREATE INDEX changes_status_idx ON changes (status);

CREATE TABLE change_items (
    change_id    UUID        NOT NULL REFERENCES changes (id) ON DELETE CASCADE,
    revision_id  UUID        NOT NULL REFERENCES revisions (id),
    added_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (change_id, revision_id)
);
CREATE INDEX change_items_revision_idx ON change_items (revision_id);

CREATE TABLE change_reviews (
    change_id    UUID        NOT NULL REFERENCES changes (id) ON DELETE CASCADE,
    reviewer_id  UUID        NOT NULL REFERENCES users (id),
    decision     TEXT        NOT NULL DEFAULT 'pending' CHECK (decision IN ('pending', 'approved', 'rejected')),
    comment      TEXT        NOT NULL DEFAULT '',
    decided_at   TIMESTAMPTZ,
    PRIMARY KEY (change_id, reviewer_id)
);
CREATE INDEX change_reviews_reviewer_idx ON change_reviews (reviewer_id);

-- ---------------------------------------------------------------------------
-- Audit trail
-- ---------------------------------------------------------------------------

CREATE TABLE audit_log (
    id           BIGSERIAL PRIMARY KEY,
    at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    user_id      UUID        REFERENCES users (id) ON DELETE SET NULL,
    username     TEXT        NOT NULL,
    action       TEXT        NOT NULL,
    entity_type  TEXT        NOT NULL,
    entity_id    UUID,
    summary      TEXT        NOT NULL,
    details      JSONB       NOT NULL DEFAULT '{}'::jsonb
);
CREATE INDEX audit_log_entity_idx ON audit_log (entity_type, entity_id);
CREATE INDEX audit_log_at_idx ON audit_log (at DESC);
